1	package stowage
2	
3	import (
4		"reflect"
5		"strings"
6		"testing"
7	)
8	
9	// 本文件为正式提交（Adjust）的重复提交识别补充回归保障：货物、舱位与
10	// 调整编号只去掉首尾空白，编号内部的冒号、竖线、空格都是编号的一部分。
11	// 围绕正式提交的可观察结果保护两件事：
12	//
13	//  1. 两份编号“连在一起读”相同、实则货物与目标各不相同的安排，复用同一
14	//     调整编号时必须收到“调整编号冲突”，不返回成功结果、不改变任何配载；
15	//  2. 同一批含标点编号的安排，仅改变首尾空白或操作顺序时必须取回首次
16	//     成功的完整变化记录且不再装卸，返回的编号保留内部字符。
17	//
18	// 同时沿用既有业务行为：普通编号照常可用、卸下目标不参与内容比较、
19	// 变化记录按编号字典序返回、承重与混装规则不变。
20	
21	// ---------- 连读后易混的两份安排必须判为不同内容 ----------
22	
23	// 货物 “G|1” 装入 “C1” 与货物 “G” 装入 “1|C1” 是两份不同安排：把货物
24	// 与目标连在一起读都是 G|1C1，但四个对象互不相同且均已合法登记。
25	// 第一份成功后，第二份复用同一调整编号必须收到调整编号冲突，且第一件
26	// 货物仍在原舱、第二件仍未装载，两舱清单与重量保持冲突提交前的状态。
27	func TestAdjustPunctuatedIDConflictAcrossLookalikePlans(t *testing.T) {
28		r := NewRegistry()
29		// 两个舱位、两件货物均合法登记，重量与目的地不会导致拒绝。
30		mustRegisterCompartment(t, r, "C1", 1000)
31		mustRegisterCompartment(t, r, "1|C1", 1000)
32		mustRegisterCargo(t, r, "G|1", 10, "X", true)
33		mustRegisterCargo(t, r, "G", 10, "X", true)
34	
35		// 第一份安排：G|1 装入 C1。
36		first := mustAdjust(t, r, "a|1", []Op{
37			{Kind: OpLoad, CargoID: "G|1", Target: "C1"},
38		})
39		wantFirst := &AdjustmentResult{
40			ID: "a|1",
41			CargoChanges: []CargoChange{
42				{CargoID: "G|1", From: "", To: "C1"},
43			},
44			CompartmentChanges: []CompartmentChange{
45				{CompartmentID: "C1", WeightBefore: 0, WeightAfter: 10},
46			},
47		}
48		if !reflect.DeepEqual(first, wantFirst) {
49			t.Fatalf("首次结果应原样保留含竖线的编号: %+v", first)
50		}
51	
52		// 冲突提交前快照。
53		compBefore := snapshotCompartments(r, "C1", "1|C1")
54		cargoBefore := snapshotCargo(r, "G|1", "G")
55	
56		// 第二份安排：G 装入 1|C1。沿用同一调整编号（带首尾空白）提交，
57		// 必须被拒绝且不返回成功结果——竖线是编号的一部分，不是分隔符，
58		// 不能因为两份安排连读后相同就视为同一次调整。
59		se := submitExpectReject(t, r, "  a|1  ", []Op{
60			{Kind: OpLoad, CargoID: "G", Target: "1|C1"},
61		})
62		if se.Kind != ErrAdjustmentIDConflict {
63			t.Fatalf("应报告调整编号冲突，实际 Kind=%s ID=%q", se.Kind, se.ID)
64		}
65		// 结构化错误按去首尾空白后的值说明涉及的调整编号；冲突错误不指向
66		// 任何货物或舱位。
67		if se.AdjustmentID != "a|1" || se.ID != "a|1" {
68			t.Fatalf("错误应携带调整编号 a|1，实际 ID=%q AdjustmentID=%q",
69				se.ID, se.AdjustmentID)
70		}
71		if !strings.Contains(se.Error(), "a|1") {
72			t.Fatalf("错误说明应包含涉及的调整编号 a|1: %s", se.Error())
73		}
74	
75		// 两舱清单、已用与剩余重量，以及两件货物的状态，均与提交前一致。
76		assertCompartmentsUnchanged(t, r, compBefore)
77		assertCargoUnchanged(t, r, cargoBefore)
78	
79		// 直接回查：第一件仍在原目标舱位，第二件仍未装载。
80		g1, _ := r.Cargo("G|1")
81		if !g1.Loaded || g1.CompartmentID != "C1" {
82			t.Fatalf("G|1 应仍在 C1: %+v", g1)
83		}
84		g, _ := r.Cargo("G")
85		if g.Loaded || g.CompartmentID != "" {
86			t.Fatalf("G 应仍未装载: %+v", g)
87		}
88		c1, _ := r.Compartment("C1")
89		if c1.UsedWeight != 10 || c1.RemainingWeight != 990 ||
90			!reflect.DeepEqual(cargoIDs(*c1), []string{"G|1"}) {
91			t.Fatalf("C1 应仍只装有 G|1、占用 10 千克: %+v", c1)
92		}
93		c1alt, _ := r.Compartment("1|C1")
94		if c1alt.UsedWeight != 0 || c1alt.RemainingWeight != 1000 || len(c1alt.Cargo) != 0 {
95			t.Fatalf("1|C1 应仍为空舱: %+v", c1alt)
96		}
97	
98		// 第二份安排换一个未使用的调整编号即可正常成功：被拒的是内容识别，
99		// 不是对象合法性；第一份的配载不受影响。
100		second := mustAdjust(t, r, "a|2", []Op{
101			{Kind: OpLoad, CargoID: "G", Target: "1|C1"},
102		})
103		if !reflect.DeepEqual(second.CargoChanges, []CargoChange{
104			{CargoID: "G", From: "", To: "1|C1"},
105		}) {
106			t.Fatalf("第二份安排应按 G -> 1|C1 生效: %+v", second.CargoChanges)
107		}
108		g, _ = r.Cargo("G")
109		if g.CompartmentID != "1|C1" {
110			t.Fatalf("G 应已装入 1|C1: %+v", g)
111		}
112		g1, _ = r.Cargo("G|1")
113		if g1.CompartmentID != "C1" {
114			t.Fatalf("G|1 应仍在 C1: %+v", g1)
115		}
116		// 首次记录仍可按原编号原内容取回。
117		again, err := r.Adjust("a|1", []Op{{Kind: OpLoad, CargoID: "G|1", Target: "C1"}})
118		if err != nil {
119			t.Fatalf("原编号原内容应仍返回首次结果: %v", err)
120		}
121		if !reflect.DeepEqual(again, wantFirst) {
122			t.Fatalf("取回的应是首次记录: %+v", again)
123		}
124	}
125	
126	// ---------- 首尾空白与排列顺序不影响含标点编号的重复识别 ----------
127	
128	// 含竖线、冒号、内部空格的同一批安排，仅改变货物、目标舱位与调整编号
129	// 的首尾空白、改变操作排列顺序，应返回首次成功保存的完整变化记录，
130	// 不再执行装载；结果编号沿用去首尾空白后的值，内部字符原样保留。
131	// 之后另有正常调整改变当前配载时，原内容再次提交仍只回放首次记录，
132	// 当前配载保持不变。
133	func TestAdjustPunctuatedIDIdempotentUnderWhitespaceAndOrder(t *testing.T) {
134		r := NewRegistry()
135		// 舱位编号含内部空格与冒号，互不相同；C3 供之后的正常调整使用。
136		mustRegisterCompartment(t, r, "C 1", 100)
137		mustRegisterCompartment(t, r, "C:2", 100)
138		mustRegisterCompartment(t, r, "C3", 100)
139		mustRegisterCargo(t, r, "G|1", 10, "X", true)
140		mustRegisterCargo(t, r, "G:2", 10, "X", true)
141	
142		first := mustAdjust(t, r, "a:1|2", []Op{
143			{Kind: OpLoad, CargoID: "G|1", Target: "C 1"},
144			{Kind: OpLoad, CargoID: "G:2", Target: "C:2"},
145		})
146		// 完整首次记录：编号只去首尾空白、内部字符保留；货物与舱位变化均按
147		// 编号字典序（字节序）排列——':'(0x3A) < '|'(0x7C)，故 G:2 在
148		// G|1 前；' '(0x20) < ':'(0x3A)，故 C 1 在 C:2 前。
149		wantFirst := &AdjustmentResult{
150			ID: "a:1|2",
151			CargoChanges: []CargoChange{
152				{CargoID: "G:2", From: "", To: "C:2"},
153				{CargoID: "G|1", From: "", To: "C 1"},
154			},
155			CompartmentChanges: []CompartmentChange{
156				{CompartmentID: "C 1", WeightBefore: 0, WeightAfter: 10},
157				{CompartmentID: "C:2", WeightBefore: 0, WeightAfter: 10},
158			},
159		}
160		if !reflect.DeepEqual(first, wantFirst) {
161			t.Fatalf("首次结果应保留编号内部字符并按字典序排列: %+v", first)
162		}
163	
164		// 仅改变各编号的首尾空白并倒置操作顺序：识别为同一批安排，返回首次
165		// 保存的完整记录。注意 “ C 1 ” 去空白后必须仍是 “C 1”，不能被
166		// 替换成 “C1”。
167		again, err := r.Adjust("\t a:1|2 \n", []Op{
168			{Kind: OpLoad, CargoID: " G:2 ", Target: "  C:2  "},
169			{Kind: OpLoad, CargoID: " G|1 ", Target: " C 1 "},
170		})
171		if err != nil {
172			t.Fatalf("首尾空白与顺序变化不应影响重复识别: %v", err)
173		}
174		if !reflect.DeepEqual(again, wantFirst) {
175			t.Fatalf("应原样返回首次完整变化记录: %+v", again)
176		}
177	
178		// 没有重新装载：两舱各只占用 10 千克，货物归属不变。
179		cs1, _ := r.Compartment("C 1")
180		if cs1.UsedWeight != 10 || cs1.RemainingWeight != 90 ||
181			!reflect.DeepEqual(cargoIDs(*cs1), []string{"G|1"}) {
182			t.Fatalf("重复提交不应再次装载，C 1 应仍只有 G|1: %+v", cs1)
183		}
184		cs2, _ := r.Compartment("C:2")
185		if cs2.UsedWeight != 10 || cs2.RemainingWeight != 90 ||
186			!reflect.DeepEqual(cargoIDs(*cs2), []string{"G:2"}) {
187			t.Fatalf("重复提交不应再次装载，C:2 应仍只有 G:2: %+v", cs2)
188		}
189	
190		// 之后一次正常调整改变当前配载：把 G|1 从 C 1 移到 C3。
191		mustAdjust(t, r, "later", []Op{
192			{Kind: OpMove, CargoID: "G|1", Target: "C3"},
193		})
194		gp, _ := r.Cargo("G|1")
195		if gp.CompartmentID != "C3" {
196			t.Fatalf("前置条件：G|1 应已移到 C3: %+v", gp)
197		}
198	
199		// 原内容再次提交：仍取回首次记录（G|1 从未装载变为 C 1 的历史变化），
200		// 但不重新装卸——G|1 必须留在 C3，空出来的 C 1 不应被重新占用。
201		replay, err := r.Adjust("a:1|2", []Op{
202			{Kind: OpLoad, CargoID: "G:2", Target: "C:2"},
203			{Kind: OpLoad, CargoID: "G|1", Target: "C 1"},
204		})
205		if err != nil {
206			t.Fatalf("当前配载改变后原内容重交仍应成功回放: %v", err)
207		}
208		if !reflect.DeepEqual(replay, wantFirst) {
209			t.Fatalf("应继续取回首次记录，而非按当前配载重算: %+v", replay)
210		}
211		gp, _ = r.Cargo("G|1")
212		if gp.CompartmentID != "C3" {
213			t.Fatalf("回放不得把 G|1 移回 C 1: %+v", gp)
214		}
215		gc, _ := r.Cargo("G:2")
216		if gc.CompartmentID != "C:2" {
217			t.Fatalf("回放不得重复装载 G:2: %+v", gc)
218		}
219		cs1, _ = r.Compartment("C 1")
220		if cs1.UsedWeight != 0 || cs1.RemainingWeight != 100 || len(cs1.Cargo) != 0 {
221			t.Fatalf("C 1 应保持空舱: %+v", cs1)
222		}
223		cs3, _ := r.Compartment("C3")
224		if cs3.UsedWeight != 10 || !reflect.DeepEqual(cargoIDs(*cs3), []string{"G|1"}) {
225			t.Fatalf("C3 应保留当前配载 G|1: %+v", cs3)
226		}
227		cs2, _ = r.Compartment("C:2")
228		if cs2.UsedWeight != 10 {
229			t.Fatalf("C:2 应保持 10 千克: %+v", cs2)
230		}
231	}
232	
233	// ---------- 冒号与内部空格同属编号内容 ----------
234	
235	// 冒号同样是编号的一部分；编号内部保留空格的对象必须与删除该空格后的
236	// 对象区分。这些内容识别问题必须先于货物状态检查报告为调整编号冲突，
237	// 在承重与混装都合法的前提下不能误报成货物状态不符，也不能误判为同一
238	// 内容而回放首次记录。
239	func TestAdjustPunctuatedIDColonAndInternalSpaceAreContent(t *testing.T) {
240		r := NewRegistry()
241		// 冒号、内部空格都属于编号：三组舱位、三件货物互不相同，全部合法登记。
242		for _, id := range []string{"C:1", "C1", "C 1"} {
243			mustRegisterCompartment(t, r, id, 1000)
244		}
245		for _, id := range []string{"G:1", "G1", "G 1"} {
246			mustRegisterCargo(t, r, id, 10, "X", true)
247		}
248	
249		// G:1 装入 C:1，调整编号本身也含冒号。
250		mustAdjust(t, r, "a:1", []Op{
251			{Kind: OpLoad, CargoID: "G:1", Target: "C:1"},
252		})
253		// 同一调整编号提交 G1 -> C1：货物与目标都不同（冒号属于编号），
254		// 必须报告调整编号冲突；若错误地删除冒号，两份内容会被混为一谈。
255		se := submitExpectReject(t, r, "a:1", []Op{
256			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
257		})
258		if se.Kind != ErrAdjustmentIDConflict || se.AdjustmentID != "a:1" {
259			t.Fatalf("冒号编号应按内容冲突拒绝，实际 Kind=%s AdjustmentID=%q",
260				se.Kind, se.AdjustmentID)
261		}
262	
263		// G 1（内部空格）装入 C 1（内部空格），调整编号同样含内部空格。
264		first := mustAdjust(t, r, "a 2", []Op{
265			{Kind: OpLoad, CargoID: "G 1", Target: "C 1"},
266		})
267		wantFirst := &AdjustmentResult{
268			ID: "a 2",
269			CargoChanges: []CargoChange{
270				{CargoID: "G 1", From: "", To: "C 1"},
271			},
272			CompartmentChanges: []CompartmentChange{
273				{CompartmentID: "C 1", WeightBefore: 0, WeightAfter: 10},
274			},
275		}
276		if !reflect.DeepEqual(first, wantFirst) {
277			t.Fatalf("首次结果应保留编号内部空格: %+v", first)
278		}
279	
280		// 仅改变各编号的首尾空白：取回首次记录，结果编号是去首尾空白后
281		// 仍含内部空格的值，不能被替换成去掉空格的 G1 / C1 / a2。
282		repadded, err := r.Adjust("  a 2 \t", []Op{
283			{Kind: OpLoad, CargoID: "  G 1  ", Target: "\tC 1\t"},
284		})
285		if err != nil {
286			t.Fatalf("首尾空白变化应识别为原调整: %v", err)
287		}
288		if !reflect.DeepEqual(repadded, wantFirst) {
289			t.Fatalf("应返回含内部空格的首次记录: %+v", repadded)
290		}
291	
292		// 同一编号改交 G1 -> C 1：内容不同（内部空格属于编号）。若先按
293		// 当前状态校验再做内容比较、或在编号识别时删除内部空格，这里会把
294		// G1 误认成已装载的 G 1 而误报“状态不符”；正确行为是调整编号冲突。
295		se = submitExpectReject(t, r, "a 2", []Op{
296			{Kind: OpLoad, CargoID: "G1", Target: "C 1"},
297		})
298		if se.Kind != ErrAdjustmentIDConflict {
299			t.Fatalf("内部空格差异应报调整编号冲突，而非 %s（%s）", se.Kind, se.Error())
300		}
301		if se.AdjustmentID != "a 2" {
302			t.Fatalf("错误应携带含内部空格的调整编号，实际 %q", se.AdjustmentID)
303		}
304	
305		// 三个对象始终各自独立：G1 从未被装载，G:1 在 C:1，G 1 在 C 1。
306		gPlain, _ := r.Cargo("G1")
307		if gPlain.Loaded || gPlain.CompartmentID != "" {
308			t.Fatalf("G1 不应因编号混淆被装载: %+v", gPlain)
309		}
310		gColon, _ := r.Cargo("G:1")
311		if gColon.CompartmentID != "C:1" {
312			t.Fatalf("G:1 应仍在 C:1: %+v", gColon)
313		}
314		gSpace, _ := r.Cargo("G 1")
315		if gSpace.CompartmentID != "C 1" {
316			t.Fatalf("G 1 应仍在 C 1: %+v", gSpace)
317		}
318		// G1 用新编号装入 C1 是一份独立的合法安排。
319		mustAdjust(t, r, "a3", []Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}})
320		cPlain, _ := r.Compartment("C1")
321		if !reflect.DeepEqual(cargoIDs(*cPlain), []string{"G1"}) || cPlain.UsedWeight != 10 {
322			t.Fatalf("C1 应只装有独立对象 G1: %+v", cPlain)
323		}
324		cSpace, _ := r.Compartment("C 1")
325		if !reflect.DeepEqual(cargoIDs(*cSpace), []string{"G 1"}) {
326			t.Fatalf("C 1 应仍只装有 G 1: %+v", cSpace)
327		}
328	}
329	
330	// ---------- 含标点编号下卸下目标仍被忽略 ----------
331	
332	// 既有行为保持：卸下操作不参与内容比较的目标值，在编号含竖线、冒号时
333	// 同样不影响重复识别——填另一个含竖线的已登记舱位或无法解析的值，都只
334	// 回放首次记录，不报冲突、不再次装卸。
335	func TestAdjustPunctuatedIDUnloadTargetStillIgnored(t *testing.T) {
336		r := NewRegistry()
337		mustRegisterCompartment(t, r, "C1", 100)
338		mustRegisterCompartment(t, r, "1|C1", 100)
339		mustRegisterCargo(t, r, "G|1", 10, "X", true)
340		mustAdjust(t, r, "init", []Op{
341			{Kind: OpLoad, CargoID: "G|1", Target: "C1"},
342		})
343	
344		first := mustAdjust(t, r, "u:1", []Op{
345			{Kind: OpUnload, CargoID: " G|1 "},
346		})
347		wantFirst := &AdjustmentResult{
348			ID: "u:1",
349			CargoChanges: []CargoChange{
350				{CargoID: "G|1", From: "C1", To: ""},
351			},
352			CompartmentChanges: []CompartmentChange{
353				{CompartmentID: "C1", WeightBefore: 10, WeightAfter: 0},
354			},
355		}
356		if !reflect.DeepEqual(first, wantFirst) {
357			t.Fatalf("首次卸下结果异常: %+v", first)
358		}
359	
360		for _, target := range []string{"1|C1", "x|y:z", "  "} {
361			got, err := r.Adjust("  u:1 ", []Op{
362				{Kind: OpUnload, CargoID: "G|1", Target: target},
363			})
364			if err != nil {
365				t.Fatalf("卸下目标 %q 不应影响重复识别: %v", target, err)
366			}
367			if !reflect.DeepEqual(got, wantFirst) {
368				t.Fatalf("卸下目标 %q 变化时应返回首次记录: %+v", target, got)
369			}
370		}
371		g, _ := r.Cargo("G|1")
372		if g.Loaded || g.CompartmentID != "" {
373			t.Fatalf("重复提交不应再次装卸，G|1 应保持未装载: %+v", g)
374		}
375		c1, _ := r.Compartment("C1")
376		if c1.UsedWeight != 0 || c1.RemainingWeight != 100 || len(c1.Cargo) != 0 {
377			t.Fatalf("C1 应保持空舱: %+v", c1)
378		}
379	}
