import (
	"errors"
	"math"
	"testing"
)

// requireError 断言 err 是 *Error 且 Kind 匹配。
func requireError(t *testing.T, err error, kind ErrorKind) *Error {
	t.Helper()
	if err == nil {
		t.Fatalf("期望错误 %s，实际为 nil", kind)
	}
	var se *Error
	if !errors.As(err, &se) {
		t.Fatalf("期望 *Error，实际为 %T: %v", err, err)
	}
	if se.Kind != kind {
		t.Fatalf("期望错误 %s，实际为 %s（%v）", kind, se.Kind, err)
	}
	return se
}

// ---------- 登记 ----------

