}

// errKind 取出错误的种类供 requireError 原样比对（previewExpectReject
// 只断言“是 *Error”，种类由调用方另行核对）。
func errKind(err error) ErrorKind {
	if se, ok := err.(*Error); ok {
		return se.Kind
	}
	return ErrOK
}

